const root=document.createElement('div');root.className='ch-root';root.setAttribute('dir','rtl');document.body.appendChild(root);
const pill=document.createElement('button');pill.className='ch-pill';pill.innerHTML='<i class="ch-pill-dot"></i><span class="ch-pill-t">زنجیرهٔ عملیات</span><span class="ch-pill-m"></span><span class="ch-ring"><svg viewBox="0 0 20 20"><circle cx="10" cy="10" r="8"/><circle class="pv" cx="10" cy="10" r="8"/></svg></span>';pill.onclick=()=>open();root.appendChild(pill);
